   class TransactionRepository {
     final AppDatabase _db;

     Future<void> _enqueueUpdate(String entityId, Map<String, dynamic> payload) async {
       // تحقق من وجود pending_create لنفس entityId
       final existing = await _db.syncQueueItems
         .select()
         .where((q) => q.entityId.equals(entityId))
         .get();

       if (existing.isNotEmpty) {
         // دمج الـ payload بدلاً من إضافة صف جديد
         final merged = {...existing.first.payload, ...payload};
         await _db.syncQueueItems.update(existing.first.id).go(
           SyncQueueItem(
             payload: merged,
             attemptCount: 0, // reset للعودة إلى البداية
           ),
         );
       } else {
         // إضافة صف جديد
         await _db.syncQueueItems.insert(SyncQueueItem(
           entityId: entityId,
           operationType: 'update',
           payload: payload,
           attemptCount: 0,
           createdAt: DateTime.now(),
         ));
       }
     }
   }
   ```

