1. تعديل _enqueueDelete() في TransactionRepository:
   ```dart
   Future<void> deleteTransaction(String entityId) async {
     // تحقق من وجود pending_create لنفس entityId
     final pendingCreate = await _db.syncQueueItems
       .select()
       .where((q) => q.entityId.equals(entityId) & q.operationType.equals('create'))
       .getSingleOrNull();

     if (pendingCreate != null) {
       // الصف لم يصل Supabase بعد → احذف من الـ DB محلياً فقط
       await _db.transactions.delete().where((t) => t.id.equals(entityId)).go();
       await _db.syncQueueItems.delete().where((q) => q.id.equals(pendingCreate.id)).go();
       return; // لا تُضف delete إلى القائمة
     }

     // إذا لم يكن pending_create، احذف جميع العمليات السابقة لنفس entityId
     await _db.syncQueueItems
       .delete()
       .where((q) => q.entityId.equals(entityId))
       .go();

     // أضف delete operation
     await _db.syncQueueItems.insert(SyncQueueItem(
       entityId: entityId,
       operationType: 'delete',
       payload: {},
       attemptCount: 0,
       createdAt: DateTime.now(),
     ));
   }
   ```

2. إنشاء _processQueue() في SyncService:
   ```dart
   Future<void> _processQueue() async {
     // ترتيب العمليات: creates أولاً ← updates ثانياً ← deletes أخيراً
     final items = await _db.syncQueueItems
       .select()
       .orderBy([/* order by operation_type */])
       .get();

     final ordered = <SyncQueueItem>[];
     ordered.addAll(items.where((i) => i.operationType == 'create'));
     ordered.addAll(items.where((i) => i.operationType == 'update'));
     ordered.addAll(items.where((i) => i.operationType == 'delete'));

     for (final item in ordered) {
       await _processSingleItem(item);
     }
   }
   ```

3. تطبيق exponential backoff للمحاولات الفاشلة:
   ```dart
   Future<void> _processSingleItem(SyncQueueItem item) async {
     try {
       // استدعاء Supabase
       await _syncToSupabase(item);
       // حذف من القائمة بعد النجاح
       await _db.syncQueueItems.delete().where((i) => i.id.equals(item.id)).go();
     } catch (e) {
       // زيادة attemptCount وحفظ آخر محاولة
       final newAttemptCount = item.attemptCount + 1;
       if (newAttemptCount <= 5) {
         final backoffMs = 1000 * (2 ^ (newAttemptCount - 1)); // exponential
         await _db.syncQueueItems.update(item.id).go(
           item.copyWith(attemptCount: newAttemptCount, lastAttemptAt: DateTime.now()),
         );
       } else {
         // 5 محاولات فاشلة → حفظ للمراجعة اليدوية (error_log table)
         await _recordFailedSync(item, e);
       }
       rethrow;
     }
   }
   ```

