   class TransactionsScreen extends StatefulWidget {
     // ...
   }

   class _TransactionsScreenState extends State<TransactionsScreen> {
     late StreamSubscription<List<SyncQueueItem>> _syncQueueSubscription;
     int _pendingCount = 0;

     @override
     void initState() {
       super.initState();

       // مراقبة قائمة المزامنة
       _syncQueueSubscription = AppDatabase()
         .syncQueueItems
         .select()
         .watch()
         .listen((items) {
         setState(() => _pendingCount = items.length);
       });
     }

     @override
     void dispose() {
       _syncQueueSubscription.cancel();
       super.dispose();
     }

     @override
     Widget build(BuildContext context) {
       return Scaffold(
         appBar: AppBar(
           title: Column(
             crossAxisAlignment: CrossAxisAlignment.start,
             children: [
               Text('المعاملات'),
               if (_pendingCount > 0)
                 Text(
                   '$_pendingCount قيد الانتظار',
                   style: Theme.of(context).textTheme.bodySmall?.copyWith(
                     color: Colors.orange[600],
